impl Solution {
    pub fn decompress_rl_elist(nums: Vec<i32>) -> Vec<i32> {
        let mut result = Vec::new();
        for i in (0..nums.len()).step_by(2) {
            let value = nums[i + 1];
            let count = nums[i] as usize;
            result.extend(std::iter::repeat(value).take(count));
        }
        result
    }
}

